const body = ($input.first().json && $input.first().json.body) || {};
const text = (body.text || '').toString().trim();
if (!text) throw new Error('Missing body.text (the recognized speech from the companion app)');
if (text.length > 2000) throw new Error('text too long (>2000 chars)');
const voice_id = (body.voice_id || '').toString().trim();
if (!/^[A-Za-z0-9]{8,40}$/.test(voice_id)) throw new Error('Missing/invalid body.voice_id (copy it from the ElevenLabs voice library)');
return [{ json: { text, voice_id } }];

const raw = $json && $json.content && $json.content[0] && $json.content[0].text;
if (!raw || !raw.trim()) throw new Error('LLM returned empty reply');
return [{ json: { reply: raw.trim(), voice_id: $('Validate Input').item.json.voice_id } }];
